const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2), clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
const dateAt=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(d), today=()=>dateAt(), plus=(d,n)=>{let t=new Date(d+'T12:00:00+06:00');t.setUTCDate(t.getUTCDate()+n);return dateAt(t)}, weekOf=d=>plus(d,-((new Date(d+'T12:00:00+06:00').getUTCDay()+1)%7)), nice=d=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',weekday:'short',timeZone:'Asia/Dhaka'}).format(new Date(d+'T12:00:00+06:00'));
const SOURCE='https://livemcq.com/central-routine/', PROGRAMS={beginner:'BCS Beginners · 200 days',model:'Weekly full model test',vocab:'Vocabulary Booster',grammar:'English Wizard',bank:'Bank recruitment',iba:'IBA faculty-based',grade:'9th–13th grade',eee:'EEE Job Solution'}, ORDER=['beginner','model','vocab','grammar','bank','iba','grade'], statusNames={planned:'Planned',completed:'On-time',missed:'Missed',recovered:'Recovered',skipped:'Intentionally skipped',deferred:'Deferred',unconfirmed:'Unconfirmed'}, seed=[['2026-11-26','grammar','Classes 29–31: spelling, confusable words, one-word substitutions, collocations, analogy and cloze exercises',40],['2026-11-26','grade','Prepositions, linkers, number, gender, vocabulary and idioms (G–I)',30],['2026-11-26','bank','Previous private bank recruitment paper',50],['2026-11-27','model','Full BCS mock',200],['2026-11-28','beginner','Bangladesh national symbols, awards, culture, geography and recent affairs'],['2026-12-04','model','Full BCS mock',200],['2026-12-04','beginner','Biology: plant and animal diversity, reproduction, genetics, human physiology and nutrition'],['2026-12-04','iba','Full IBA mock'],['2026-12-11','model','Full BCS mock',200],['2026-12-11','beginner','Bangladesh agriculture, food production, industry, trade and finance'],['2026-12-18','model','Full BCS mock',200],['2026-12-18','beginner','Bangla grammar: word classes, roots, affixes and tense'],['2026-12-18','vocab','Review word groups 25–26'],['2026-12-25','model','Full BCS mock',200],['2026-12-01','beginner','Idioms, phrases, composition, narration, tag questions and sentence types'],['2026-12-01','bank','Full bank recruitment model test',100],['2026-12-01','iba','Revision of the previous four tests'],['2026-12-02','vocab','Word group 24; job vocabulary 351–365; idioms 541–562'],['2026-12-08','beginner','Revision of previous six beginner exams'],['2026-12-08','bank','Full bank recruitment model test',100],['2026-12-09','iba','Vocabulary revision: spelling, meanings, synonyms and antonyms'],['2026-12-15','grammar','Full syllabus revision test'],['2026-12-16','bank','Bank English: revision of tests 10–11'],['2026-12-17','iba','Computer and ICT previous questions']];
const goalTemplates=[['GRE vocabulary','words',100,5],['EEE Job Solution','questions',100,5],['GRE / IBA mathematics','problems',50,5],['Editorial reading','articles',5,1],['Written practice','exercises',2,1],['Previous job questions','sets',3,1],['Weak-topic revision','topics',5,1]], booksDefault=['English for Competitive Exams','বাংলা ভাষা ও সাহিত্য জিজ্ঞাসা — সৌমিত্র শেখর','MP3 বাংলাদেশ বিষয়াবলি','MP3 আন্তর্জাতিক বিষয়াবলি','Rony Parvej EEE Job Solution','Manhattan 5 lb. GRE Practice Problems'];
function fresh(){return {version:1,exams:seed.map((x,i)=>({id:'seed'+i,date:x[0],programme:x[1],topic:x[2],marks:x[3]||'',end:'',source:SOURCE,selected:false,status:'planned',note:'',result:null})),goals:goalTemplates.map((x,i)=>({id:'g'+i,name:x[0],unit:x[1],target:x[2],step:x[3]})),weeks:{},words:[],topics:[],books:booksDefault.map(name=>({id:id(),name,total:0,done:0})),jobs:[],logs:[],settings:{enabled:ORDER.slice(),dark:false,hours:5,brief:'09:00',evening:'21:00',reminders:true},notices:[],seen:{}}}
let state;try{state=JSON.parse(localStorage.getItem('project2029-v1'))||fresh()}catch{state=fresh()}let page='Today',routineDate=today(),week=weekOf(today()),flashIndex=0,reveal=false,filter='all',timer=null,toastTimer,importBuffer=[];
function save(){try{localStorage.setItem('project2029-v1',JSON.stringify(state));cloudQueue();return true}catch(e){toast('Storage full or unavailable. Export a backup before leaving.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function go(p){page=p;render();window.scrollTo(0,0)}function change(){save();render()}
function effective(e){if(e.status!=='planned')return e.status;if(!e.selected)return 'deferred';if(e.end?Date.now()>new Date(e.date+'T'+e.end+':00+06:00').getTime():e.date<today())return 'unconfirmed';return 'planned'}
function selectedCount(d){return state.exams.filter(e=>(e.selected&&e.date===d&&e.status!=='skipped'&&e.status!=='deferred')||(e.status==='recovered'&&e.recoveryDate===d&&e.date!==d)).length}
function autoPick(){let ds=[...new Set(state.exams.map(e=>e.date))];for(let d of ds){if(d<today())continue;let candidates=state.exams.filter(e=>e.date===d&&state.settings.enabled.includes(e.programme)&&e.status==='planned'&&!e.manual&&!e.selected).sort((a,b)=>ORDER.indexOf(a.programme)-ORDER.indexOf(b.programme));let slots=2-selectedCount(d);for(let e of candidates.slice(0,Math.max(0,slots)))e.selected=true}}
function stats(exams=state.exams){let result={on:0,miss:0,recovered:0,unknown:0,upcoming:0,selected:0};for(let e of exams){let s=effective(e);if(!e.selected&& !['completed','missed','recovered'].includes(s))continue;if(s==='skipped'||s==='deferred')continue;result.selected++;if(s==='completed')result.on++;else if(s==='missed')result.miss++;else if(s==='recovered')result.recovered++;else if(s==='unconfirmed')result.unknown++;else result.upcoming++}let den=result.on+result.miss+result.recovered;result.rate=den?Math.round(result.on/den*100):null;return result}
function weekProgress(g){return state.weeks[week]?.[g.id]||0}function progress(g,n){state.weeks[week]??={};state.weeks[week][g.id]=Math.max(0,n);change()}
const nav=[['Today','⌂'],['Routine','▦'],['Weekly goals','◎'],['Vocabulary','Aa'],['Performance','▥'],['Revision','↻'],['Library','▤'],['Career','◇'],['Settings','⚙']];
function render(){document.documentElement.classList.toggle('dark',!!state.settings.dark);$('#heading').textContent=page;$('#dateLabel').textContent=nice(today())+' · DHAKA';$('#nav').innerHTML=nav.map(([n,i])=>`<button class="${page===n?'active':''}" data-go="${esc(n)}"><span class="navicon">${i}</span>${n}</button>`).join('');$('#bellCount').textContent=state.notices.filter(n=>!n.read).length;$('#view').innerHTML=({Today:dashboard,Routine:routine,'Weekly goals':goals,Vocabulary:vocabulary,Performance:performance,Revision:revision,Library:library,Career:career,Settings:settings}[page]||dashboard)()}
const stat=(label,value,sub='')=>`<div class="card stat"><small>${esc(label)}</small><div class="number">${esc(value)}</div><small>${esc(sub)}</small></div>`, bar=(n,m)=>`<div class="bar"><i style="width:${clamp(m?n/m*100:0,0,100)}%"></i></div>`, section=(n,action='')=>`<div class="section"><h2>${esc(n)}</h2>${action}</div>`, btn=(label,act,arg='',cls='')=>`<button class="${cls}" data-act="${act}" data-id="${esc(arg)}">${esc(label)}</button>`, empty=s=>`<div class="empty">${esc(s)}</div>`, fmt=e=>esc(PROGRAMS[e.programme]||e.programme);
function guide(e){let t=e.topic.toLowerCase(), resource='Live MCQ topic notes and previous questions',steps=['Outline the exact syllabus above; identify unfamiliar subtopics.','Read the relevant chapter and make a one-page recall sheet.','Solve a timed topic quiz; log wrong answers and guesses.'];let mins=60;if(e.programme==='vocab'||/vocab|synonym|idiom/.test(t)){resource='Live MCQ vocabulary PDFs; English for Competitive Exams; Magoosh for supplementary words';steps=['Extract the listed words or expressions, with meanings and usage.','Recall meanings, synonyms and antonyms without looking; practise confusing pairs.','Attempt a timed quiz and save unfamiliar words for review.'];mins=45}if(/constitution|বাংলাদেশ|bangladesh|history/.test(t)){resource='MP3 বাংলাদেশ বিষয়াবলি; official Constitution or Banglapedia as relevant';steps=['Read the relevant syllabus headings and verify dates or articles.','Build a compact fact sheet and practise active recall.','Solve previous questions and cross-check disputed facts.'];mins=90}if(/grammar|narration|preposition|sentence|verb|composition/.test(t)){resource='English for Competitive Exams; Wren & Martin';steps=['Review rules for each listed grammar topic.','Write two examples and common exceptions per rule.','Solve 25–40 timed questions, then check explanations.'];mins=60}if(/math|quant|algebra|geometry|গণিত/.test(t)){resource='NCTB mathematics; Manhattan 5 lb. GRE for supplementary drills';steps=['Write formulas and solve two worked examples per subtopic.','Practise 15–25 timed problems without a calculator.','Review slow methods and arithmetic mistakes.'];mins=60}if(/full|model|revision|রিভিশন/.test(t)){resource='Previous Live MCQ exams, mistake notebook and relevant guidebooks';steps=['Review the specified previous exams or subject coverage.','Prioritise weak topics and previously guessed answers.','Take the mock under exam conditions; review the result.'];mins=75}return {resource,steps,mins}}
function examCard(e,withGuide=false){let s=effective(e),g=guide(e);return `<article class="exam"><div class="row"><div class="grow"><span class="pill ${['missed','unconfirmed'].includes(s)?'red':s==='deferred'?'warn':''}">${esc(statusNames[s]||s)}</span> <small>${esc(e.date)} · ${e.marks?esc(e.marks)+' marks':'Marks not specified'}</small><h3 style="margin-top:7px">${fmt(e)}</h3></div>${e.selected?btn('Unselect','select',e.id):btn('Select','select',e.id,'quiet')}</div><p>${esc(e.topic)}</p><small>${e.end?'Closes '+esc(e.end)+' BST':'Closing time unknown · verify in Live MCQ'}${e.source?' · <a href="'+SOURCE+'" target="_blank" rel="noopener">Public routine</a>':''}</small>${withGuide?`<details open><summary>Preparation guide · ${g.mins} min</summary><p><b>Resources:</b> ${esc(g.resource)}</p><ol>${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><small>Rule-based guidance; check the official syllabus for exact coverage.</small></details>`:''}<div class="actions" style="margin-top:10px">${btn('Log result','result',e.id,'primary')}${btn('Status','status',e.id)}${btn('Edit','editExam',e.id)}<a href="https://web.livemcq.com/resources/routines" target="_blank" rel="noopener">Live MCQ ↗</a></div></article>`}
function dashboard(){let d=today(),s=stats(),es=state.exams.filter(e=>e.date===d&&e.selected&&effective(e)!=='skipped'),tom=state.exams.filter(e=>e.date===plus(d,1)&&e.selected),w=weekOf(d),gs=state.goals,ratio=gs.length?Math.round(gs.reduce((a,g)=>a+clamp((state.weeks[w]?.[g.id]||0)/g.target,0,1),0)/gs.length*100):0;return `<div class="stats">${stat('Today’s exams',es.length+'/2','Selected')}${stat('Missed backlog',s.miss,s.unknown+' need confirmation')}${stat('Weekly goals',ratio+'%','Independent study')}${stat('Attendance',s.rate===null?'—':s.rate+'%','Confirmed exams only')}</div><div class="note">Live MCQ determines your daily plan. Independent preparation is measured weekly. ${state.exams.some(e=>e.date===d)?'Check closing times in Live MCQ.':'No routine entries for today. Import the latest schedule or add an exam.'}</div>${section('Today’s preparation',btn('Open routine','go','Routine'))}<div class="card">${es.length?es.map(e=>examCard(e,true)).join(''):empty('No selected exams today. Use Routine to import or select up to two.')}</div><div class="grid"><div class="card"><h2>Tomorrow</h2>${tom.length?tom.map(e=>`<p><b>${fmt(e)}</b><br><small>${esc(e.topic)}</small></p>`).join(''):empty('No selected exams imported for tomorrow.')}</div><div class="card"><h2>Recovery queue</h2><p>${s.miss} confirmed missed · ${s.unknown} unconfirmed</p>${btn('Review backlog','go','Revision','primary')}</div></div>${section('Study time',btn('Log session','log'))}<div class="card"><p>${Math.round(state.logs.filter(x=>x.date===d).reduce((a,x)=>a+x.minutes,0))} minutes logged today · ${state.settings.hours}h suggested capacity</p><small>Weekly goals do not have daily deadlines.</small></div>`}
function routine(){let es=state.exams.filter(e=>e.date===routineDate&&(filter==='all'||e.programme===filter));return `<div class="row card"><div class="actions">${btn('‹','day','-1')}<input aria-label="Routine date" type="date" id="rdate" value="${routineDate}" style="width:auto">${btn('›','day','1')}${btn('Today','day','0')}</div><div class="actions">${btn('Refresh public routine','refreshRoutine')}${btn('Import routine','import','','primary')}${btn('+ Exam','editExam')}</div></div><div class="row"><small>${selectedCount(routineDate)}/2 slots used · ${esc(nice(routineDate))}</small><select id="programFilter" style="width:auto;max-width:100%"><option value="all">All programmes</option>${ORDER.map(p=>`<option value="${p}" ${filter===p?'selected':''}>${esc(PROGRAMS[p])}</option>`).join('')}</select></div>${section('Exams for '+nice(routineDate))}<div class="card">${es.length?es.sort((a,b)=>Number(b.selected)-Number(a.selected)).map(e=>examCard(e,true)).join(''):empty('No exams imported for this date.')}</div>${section('Next 14 days')}<div class="card">${state.exams.filter(e=>e.date>routineDate&&e.date<=plus(routineDate,14)).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="goal row"><div class="grow"><small>${esc(e.date)} · ${esc(statusNames[effective(e)])}</small><div>${fmt(e)}</div><small>${esc(e.topic)}</small></div>${btn('View','jump',e.date)}</div>`).join('')||empty('No upcoming data.')}</div>`}
function goals(){let gs=state.goals;return `<div class="row card"><div><h2>Week of ${esc(week)}</h2><small>Saturday – Friday · independent goals</small></div><div class="actions">${btn('‹','week','-7')}${btn('This week','week','0')}${btn('›','week','7')}${btn('+ Goal','editGoal')}</div></div><div class="card">${gs.map(g=>{let n=weekProgress(g);return `<div class="goal"><div class="row"><div class="grow"><b>${esc(g.name)}</b><div class="muted">${n} / ${g.target} ${esc(g.unit)}</div></div><div class="actions">${btn('−'+g.step,'goalMinus',g.id)}${btn('+'+g.step,'goalPlus',g.id,'primary')}${btn('Edit','editGoal',g.id)}</div></div>${bar(n,g.target)}</div>`}).join('')}</div><div class="note">Targets reset by week, not by day. Previous weeks remain saved. Edit a goal to change its target for all displayed weeks.</div>`}
function vocabulary(){let due=state.words.filter(w=>w.due<=today()),pool=due.length?due:state.words,w=pool[flashIndex%Math.max(pool.length,1)];return `<div class="stats">${stat('Word bank',state.words.length)}${stat('Due now',due.length)}${stat('Reviewed',state.words.filter(w=>w.reps>0).length)}${stat('Mastered',state.words.filter(w=>w.reps>=4).length,'4+ successful recalls')}</div><div class="actions">${btn('+ Add word','editWord','','primary')}${btn('Import words','wordImport')}</div>${section('Recall practice')}<div class="card">${w?`<div class="flash"><div><div class="number">${esc(w.word)}</div>${reveal?`<p>${esc(w.meaning)}</p><p>${esc(w.synonyms||'')} · ${esc(w.antonyms||'')}</p><small>${esc(w.example||'')}</small>`:'<small>Recall the meaning before revealing.</small>'}</div></div><div class="actions">${reveal?btn('Again','reviewWord',w.id+'|0')+btn('Know it','reviewWord',w.id+'|1','primary'):btn('Reveal answer','reveal','','primary')}${btn('Next','nextWord')}</div>`:empty('Add vocabulary from GRE or Live MCQ to start.')}</div>${section('All words')}<div class="card">${state.words.map(w=>`<div class="goal row"><div class="grow"><b>${esc(w.word)}</b><p>${esc(w.meaning)}</p><small>Due ${esc(w.due)} · ${w.reps} successful recalls</small></div>${btn('Edit','editWord',w.id)}</div>`).join('')||empty('Your word bank is empty.')}</div>`}
function performance(){let s=stats(),rs=state.exams.filter(e=>e.result).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="stats">${stat('On-time',s.on)}${stat('Missed',s.miss)}${stat('Recovered',s.recovered)}${stat('Unconfirmed',s.unknown)}</div><div class="grid"><div class="card"><h2>Attendance by programme</h2>${ORDER.map(p=>{let a=stats(state.exams.filter(e=>e.programme===p));return `<div class="goal"><div class="row"><b>${esc(PROGRAMS[p])}</b><small>${a.rate===null?'—':a.rate+'%'}</small></div>${bar(a.on,a.on+a.miss+a.recovered)}<small>${a.on} on-time · ${a.miss} missed · ${a.recovered} recovered · ${a.unknown} unconfirmed</small></div>`}).join('')}</div><div class="card"><h2>Score history</h2>${rs.length?rs.map(e=>`<div class="goal"><div class="row"><b>${fmt(e)}</b><small>${esc(e.date)}</small></div><div>${esc(e.result.score)} / ${esc(e.result.max||e.marks||'?')}</div>${bar(Number(e.result.score),Number(e.result.max||e.marks))}<small>${e.result.correct!==''&&Number(e.result.correct)+Number(e.result.wrong)>0?Math.round(Number(e.result.correct)/(Number(e.result.correct)+Number(e.result.wrong))*100)+'% accuracy · ':''}Rank ${esc(e.result.rank||'—')}</small> ${btn('View','result',e.id)}</div>`).join(''):empty('Log your first result to view scores.')}</div></div>${section('Export')}<div class="actions">${btn('Results CSV','csv')}${btn('All data JSON','backup')}</div>`}
function revision(){let es=state.exams.filter(e=>['missed','unconfirmed'].includes(effective(e))).sort((a,b)=>ORDER.indexOf(a.programme)-ORDER.indexOf(b.programme)||a.date.localeCompare(b.date));return `<div class="note">Unconfirmed is not the same as missed. Confirm attendance first. Recovered exams count against the two-exam limit on their recovery date.</div>${section('Missed and unconfirmed exams')}<div class="card">${es.map(e=>examCard(e)).join('')||empty('No pending exam backlog.')}</div>${section('Weak topics',btn('+ Topic','editTopic'))}<div class="card">${state.topics.map(t=>`<div class="goal row"><div class="grow"><b>${esc(t.name)}</b><p>${esc(t.note)}</p><small>Due ${esc(t.due)}</small></div>${btn('Reviewed','topicReview',t.id)}${btn('Edit','editTopic',t.id)}</div>`).join('')||empty('Record weak topics here or while logging a result.')}</div>`}
function library(){return `<div class="grid"><div class="card"><div class="row"><h2>Books</h2>${btn('+ Book','editBook')}</div>${state.books.map(b=>`<div class="goal"><div class="row"><b>${esc(b.name)}</b>${btn('Edit','editBook',b.id)}</div>${bar(b.done,b.total)}<small>${b.done} / ${b.total||'—'} chapters or units</small></div>`).join('')}</div><div class="card"><h2>Study resources</h2>${[['Live MCQ central routine',SOURCE],['Live MCQ exam routines','https://web.livemcq.com/resources/routines'],['Magoosh vocabulary','https://gre.magoosh.com/flashcards/vocabulary'],['ETS GRE preparation','https://www.ets.org/gre/test-takers/general-test/prepare.html'],['Bangladesh Constitution','https://bdlaws.minlaw.gov.bd/act-367.html']].map(x=>`<p><a target="_blank" rel="noopener" href="${x[1]}">${esc(x[0])} ↗</a></p>`).join('')}<h2 style="margin-top:20px">Study log</h2>${btn('Log session','log')}${state.logs.slice(-15).reverse().map(l=>`<p>${esc(l.date)} · ${esc(l.subject)} · ${l.minutes} min</p>`).join('')}</div></div>`}
function career(){return `<div class="note">Target organisations: CAAB, BSTI, DESCO, WZPDCL, Power Grid Bangladesh, BPDB, DPDC, NESCO, BREB, EGCB, APSCL, NWPGCL; BCS, Bangladesh Bank, IBA and semiconductor employers. Add verified circulars manually.</div>${section('Applications',btn('+ Application','editJob','','primary'))}<div class="card">${state.jobs.map(j=>`<div class="goal row"><div class="grow"><b>${esc(j.org)} · ${esc(j.role)}</b><p>${esc(j.status)} · Deadline ${esc(j.deadline||'—')} · Exam ${esc(j.exam||'—')}</p><small>${esc(j.note||'')}</small></div>${btn('Edit','editJob',j.id)}</div>`).join('')||empty('No applications yet.')}</div>`}
function settings(){return `<div class="grid"><div class="card"><h2>Programmes</h2><div class="checks">${ORDER.map(p=>`<label><input type="checkbox" class="program" value="${p}" ${state.settings.enabled.includes(p)?'checked':''}>${esc(PROGRAMS[p])}</label>`).join('')}</div><p class="muted">Daily maximum: two exams, including recovery attempts.</p>${btn('Recalculate selections','auto')}</div><div class="card"><h2>Preferences</h2><label>Suggested study capacity (hours)<input type="number" id="hours" min="1" max="12" value="${state.settings.hours}"></label><label style="margin-top:10px">Morning reminder (Dhaka)<input type="time" id="brief" value="${state.settings.brief}"></label><label style="margin-top:10px">Evening reminder (Dhaka)<input type="time" id="evening" value="${state.settings.evening}"></label><div class="checks" style="margin-top:12px"><label><input type="checkbox" id="dark" ${state.settings.dark?'checked':''}>Dark theme</label><label><input type="checkbox" id="reminders" ${state.settings.reminders?'checked':''}>In-app reminders</label></div>${btn('Enable browser notifications','notify','','primary')}<p class="muted">Without a configured push server, notifications require the app to be open. Android install requires HTTPS or localhost.</p><p class="muted">Background push is not configured yet.</p></div></div>${section('Data and sync')}<div class="card"><p>Data is saved in this browser. Export backups regularly. Cloud sync uses your Supabase login.</p><div class="actions">${btn('Export backup','backup')}${btn('Restore backup','restore')}${btn('Install app','install')}</div><p class="muted">No Live MCQ credentials are stored. Public routine last refreshed: ${esc(state.settings.routineUpdated||'not yet available')}. Existing personal records are retained.</p></div>${cloudPanel()}`}
function dialog(title,html){$('#modalContent').innerHTML=`<div class="row"><h2>${esc(title)}</h2><button data-act="close" aria-label="Close">×</button></div>${html}`;if(!$('#modal').open)$('#modal').showModal()}
const field=(n,v='',type='text',extra='')=>`<label>${esc(n)}<input name="${esc(n)}" type="${type}" value="${esc(v)}" ${extra}></label>`, area=(n,v='')=>`<label class="full">${esc(n)}<textarea name="${esc(n)}">${esc(v)}</textarea></label>`, options=(n,values,v)=>`<label>${esc(n)}<select name="${esc(n)}">${values.map(([k,l])=>`<option value="${esc(k)}" ${k===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
function form(title,kind,key,body){dialog(title,`<form data-form="${kind}" data-key="${esc(key)}"><div class="formgrid">${body}</div><div class="actions"><button class="primary" type="submit">Save</button><button type="button" data-act="close">Cancel</button>${key&&['editExam','editWord','editTopic','editBook','editJob','editGoal'].includes(kind)?`<button type="button" class="danger" data-act="delete" data-id="${kind}|${esc(key)}">Delete</button>`:''}</div></form>`)}
function editExam(key){let e=state.exams.find(x=>x.id===key)||{date:routineDate,programme:'beginner',topic:'',marks:'',end:'',note:''};form('Exam details','editExam',key,field('Date',e.date,'date','required')+options('Programme',ORDER.map(p=>[p,PROGRAMS[p]]),e.programme)+area('Topic',e.topic)+field('Maximum marks',e.marks,'number','min="1"')+field('Closing time',e.end,'time')+area('Notes / references',e.note))}
function result(key){let e=state.exams.find(x=>x.id===key),r=e.result||{};form('Log result · '+PROGRAMS[e.programme],'result',key,field('Net score',r.score??'','number','step="0.01" required')+field('Maximum marks',r.max||e.marks,'number','min="1" required')+field('Correct',r.correct??'','number','min="0"')+field('Wrong',r.wrong??'','number','min="0"')+field('Skipped',r.skipped??'','number','min="0"')+field('Negative marks',r.penalty??'','number','min="0" step="0.01"')+field('Rank',r.rank??'','number','min="1"')+field('Minutes',r.minutes??'','number','min="0"')+options('Attendance',[['completed','On-time'],['recovered','Recovered after exam']],e.status==='recovered'||e.status==='missed'?'recovered':'completed')+field('Recovery date',e.recoveryDate||today(),'date')+area('Weak topics',r.weak||'')+`<label class="full">Result screenshot (optional; enter values manually)<input name="photo" type="file" accept="image/*"></label>${r.photo&&/^data:image\/jpeg;base64,/.test(r.photo)?`<img class="photo full" src="${esc(r.photo)}" alt="Saved result screenshot">`:''}<small class="full">Screenshot is saved locally with the result. Automatic extraction is not configured.</small>`)}
function editStatus(key){let e=state.exams.find(x=>x.id===key);form('Confirm exam status','status',key,options('Status',Object.entries(statusNames),e.status==='planned'?effective(e):e.status)+field('Recovery date',e.recoveryDate||today(),'date')+area('Notes',e.note||''))}
function editGeneric(kind,key){let data={editGoal:['goals','Weekly goal',x=>field('Name',x.name,'text','required')+field('Unit',x.unit,'text','required')+field('Target',x.target??10,'number','min="1" required')+field('Increment',x.step??1,'number','min="1" required')],editWord:['words','Vocabulary word',x=>field('Word',x.word,'text','required')+field('Meaning',x.meaning,'text','required')+field('Synonyms',x.synonyms)+field('Antonyms',x.antonyms)+area('Example',x.example)],editTopic:['topics','Revision topic',x=>field('Name',x.name,'text','required')+field('Due',x.due||today(),'date','required')+area('Notes',x.note)],editBook:['books','Book progress',x=>field('Name',x.name,'text','required')+field('Total units',x.total??0,'number','min="0" required')+field('Completed units',x.done??0,'number','min="0" required')],editJob:['jobs','Career application',x=>field('Organisation',x.org,'text','required')+field('Role',x.role,'text','required')+field('Deadline',x.deadline,'date')+field('Exam date',x.exam,'date')+options('Status',['Interested','Applied','Admit card','Exam attended','Interview','Offer','Closed'].map(v=>[v,v]),x.status||'Interested')+area('Notes / circular link',x.note)]}[kind];let x=state[data[0]].find(x=>x.id===key)||{};form(data[1],kind,key,data[2](x))}
function classify(s){s=s.toLowerCase();if(/নতুনদের.*বিসিএস.*(?:২০০|200)|bcs beginners|beginner/.test(s))return 'beginner';if(/ফ্রি.*(?:সাপ্তাহিক|মডেল)|সাপ্তাহিক.*মডেল|weekly.*model|free.*model/.test(s))return 'model';if(/vocabulary booster/.test(s))return 'vocab';if(/english wizard/.test(s))return 'grammar';if(/ব্যাংক|\bbank\b|অফিসার ক্যাশ ও জেনারেল/.test(s))return 'bank';if(/\biba\b/.test(s))return 'iba';if(/(?:৯ম|9th).*(?:১৩|13)/.test(s))return 'grade';return ''}
function parseRoutine(raw){let rows=[];try{let j=JSON.parse(raw);if(Array.isArray(j)){return j.map(x=>({date:String(x.date||''),programme:ORDER.includes(x.programme)?x.programme:classify(String(x.programme||'')),topic:String(x.topic||''),marks:x.marks||'',end:x.end||'',source:SOURCE})).filter(validRow)}}catch{}let d='',current=null;const push=()=>{if(current&&validRow(current))rows.push(current);current=null};for(let line of raw.split(/\r?\n/)){line=line.trim();if(!line)continue;let m=line.match(/^(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),\s+(\w+)\s+(\d{1,2}),\s+(\d{4})/i);if(m){push();let month=['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(m[1].toLowerCase())+1;d=m[3]+'-'+String(month).padStart(2,'0')+'-'+m[2].padStart(2,'0');continue}let parts=line.split(/\s*\|\s*|\t+/);if(/^\d{4}-\d{2}-\d{2}$/.test(parts[0])&&parts.length>=3){push();rows.push({date:parts[0],programme:ORDER.includes(parts[1])?parts[1]:classify(parts[1]),topic:parts[2],marks:parts[3]||'',end:parts[4]||'',source:SOURCE});continue}if(parts.length>=2){push();let p=classify(parts[0]);if(p&&d)current={date:d,programme:p,topic:parts.slice(1).join(' | '),marks:'',end:'',source:SOURCE};continue}if(current){let marks=line.match(/মার্ক[ঃ:]\s*(\d+)/);if(marks){current.marks=marks[1];continue}if(!/^পরীক্ষার সময়|^\[নির্দেশিকা|^---/.test(line))current.topic+='\n'+line}}push();return rows.filter(validRow)}

async function refreshPublicRoutine(manual=false){
 try{
  const response=await fetch('https://raw.githubusercontent.com/totoroKr/project-2029/main/routine-feed.json',{cache:'no-store'});
  if(!response.ok)throw Error('Public feed is not available yet');
  const feed=await response.json();
  if(!Array.isArray(feed.exams)||!feed.updatedAt||feed.source!==SOURCE)throw Error('Invalid routine feed');
  const rows=feed.exams.filter(validRow).filter(x=>x.date>=today());
  if(!rows.length)throw Error('No upcoming exams found; existing schedule retained');
  let added=0,updated=0;
  const norm=x=>String(x||'').toLowerCase().replace(/\s+/g,' ').trim();
  for(const row of rows){
   const same=state.exams.find(e=>e.date===row.date&&e.programme===row.programme&&(norm(e.topic)===norm(row.topic)||(row.title&&e.feedTitle===row.title)));
   if(same){if(!same.manual&&!same.result&&same.status==='planned'&&same.feedTitle&&(same.topic!==row.topic||(row.marks&&same.marks!==row.marks))){same.topic=row.topic;same.marks=row.marks||same.marks;updated++;}continue;}
   // Preserve manually curated starter entries rather than silently creating a competing slot.
   const existing=state.exams.filter(e=>e.date===row.date&&e.programme===row.programme&&!e.feedTitle);
   if(existing.length){continue;}
   state.exams.push({date:row.date,programme:row.programme,topic:row.topic,marks:row.marks||'',end:row.end||'',source:SOURCE,feedTitle:row.title||'',id:id(),selected:false,status:'planned',note:'',result:null});added++;
  }
  if(added||updated||state.settings.routineUpdated!==feed.updatedAt){state.settings.routineUpdated=feed.updatedAt;autoPick();change();}
  if(manual)toast('Routine refreshed: '+added+' new exams; existing personal records preserved.');
 }catch(e){if(manual)toast(e.message+'; use manual import if needed.');}
}

function validRow(r){return /^\d{4}-\d{2}-\d{2}$/.test(r.date)&&!isNaN(Date.parse(r.date))&&ORDER.includes(r.programme)&&r.topic.trim()&&(!r.end||/^([01]\d|2[0-3]):[0-5]\d$/.test(r.end))}
function importDialog(){dialog('Import Live MCQ routine',`<p>Open the <a href="${SOURCE}" target="_blank" rel="noopener">central routine</a>, copy the schedule text and paste it below. Or use one line per exam: <code>YYYY-MM-DD | programme | topic | marks | HH:MM</code>. JSON arrays are also accepted.</p><form data-form="previewImport"><label>Routine text<textarea name="raw" rows="9" required></textarea></label><div class="actions" style="margin-top:12px"><button class="primary">Preview import</button><button type="button" data-act="fetchRoutine">Preview public routine feed</button></div></form><p class="muted">Public source only. Always check preview against Live MCQ. Unknown closing times remain blank; exam duration is not closing time.</p>`)}
function preview(rows){importBuffer=rows;dialog('Review imported exams',`<p>${rows.length} supported rows found. Confirm topics and dates before importing. Existing exact matches will not be duplicated.</p><div class="stack">${rows.map((x,i)=>`<label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" class="importCheck" value="${i}" checked style="width:auto"><span>${esc(x.date)} · ${esc(PROGRAMS[x.programme])}<br>${esc(x.topic.slice(0,400))}</span></label>`).join('')||'<p>No supported rows detected. Try pipe-separated lines or manual entry.</p>'}</div><div class="actions" style="margin-top:15px">${btn('Import checked','commitImport','','primary')}${btn('Back','import')}</div>`)}
function setAttendance(e,s,rd){if(['completed','missed','recovered','unconfirmed'].includes(s)&&!e.selected&&selectedCount(e.date)>=2)throw Error('Both slots on original date are occupied. Unselect another exam first.');if(['completed','missed','recovered'].includes(s)&&e.date>today())throw Error('Cannot record attendance for a future exam.');if(s==='recovered'){if(!rd||rd<e.date||rd>today())throw Error('Recovery date must be on or after the exam and not in the future.');if(rd!==e.date&&!(e.status==='recovered'&&e.recoveryDate===rd)&&selectedCount(rd)>=2)throw Error('Both exam slots on recovery date are used. Choose another date.');e.recoveryDate=rd}else delete e.recoveryDate;if(['completed','missed','recovered','unconfirmed'].includes(s))e.selected=true;if(s==='skipped'||s==='deferred')e.selected=false;e.status=s;e.manual=true}
async function smallPhoto(file){if(!file||!file.size)return '';if(!file.type.startsWith('image/'))throw Error('Choose an image.');let bitmap=await createImageBitmap(file),scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();return c.toDataURL('image/jpeg',.68)}
function replace(list,key,v){let i=list.findIndex(x=>x.id===key);if(i<0)list.push(v);else list[i]=v}function download(name,content,type='application/json'){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validated(data){if(!data||data.version!==1||!['exams','goals','words','topics','books','jobs','logs','notices'].every(k=>Array.isArray(data[k]))||!data.settings||!data.weeks||!data.seen)throw Error('Invalid Project 2029 backup.');return data}
async function api(path,body,token=sessionStorage.getItem('p2029-token')||''){let r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!r.ok)throw Error('Server response '+r.status);return r.json()}
function notify(title,body,key){if(state.seen[key])return;state.seen[key]=true;state.notices.unshift({id:id(),title,body,date:today(),read:false});state.notices=state.notices.slice(0,150);save();if('Notification'in window&&Notification.permission==='granted'){if(navigator.serviceWorker?.controller)navigator.serviceWorker.ready.then(r=>r.showNotification(title,{body,tag:key,icon:'./icon-192.png'})).catch(()=>{});else try{new Notification(title,{body,tag:key})}catch{}}$('#bellCount').textContent=state.notices.filter(n=>!n.read).length}
function reminders(){if(!state.settings.reminders)return;let d=today(),time=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()),s=stats(),es=state.exams.filter(e=>e.date===d&&e.selected&&effective(e)==='planned');if(time>=state.settings.brief)notify('Today’s study plan',es.length?es.map(e=>PROGRAMS[e.programme]+': '+e.topic.split('\n')[0].slice(0,110)).join(' • '):'No selected exams imported for today. Check the Live MCQ routine.','brief'+d);if(time>=state.settings.evening)notify('Exam attendance check',`${s.miss} confirmed missed; ${s.unknown} unconfirmed. Review your backlog.`,'evening'+d);for(let e of state.exams.filter(e=>e.selected&&effective(e)==='unconfirmed'))notify('Confirm exam attendance',PROGRAMS[e.programme]+' · '+e.date+'. Mark missed or log result.','unknown'+e.id);for(let e of es){if(e.end){let delta=new Date(e.date+'T'+e.end+':00+06:00')-Date.now();if(delta>0&&delta<=7200000)notify('Exam closing soon',PROGRAMS[e.programme]+' closes '+e.end+' BST.','close'+e.id)}}if(s.miss)notify('Missed-exam backlog',`${s.miss} exams still need recovery.`, 'backlog'+d+'-'+s.miss);if(time>=state.settings.evening&&weekOf(d)!==weekOf(plus(d,1))){let ws=stats(state.exams.filter(e=>e.date>=weekOf(d)&&e.date<=d));notify('Weekly attendance',`${ws.on} on-time · ${ws.miss} missed · ${ws.recovered} recovered · ${ws.unknown} unconfirmed`,'weekly'+d)}}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.go){go(b.dataset.go);return}let a=b.dataset.act,k=b.dataset.id||'';if(!a)return;let e=state.exams.find(x=>x.id===k),g=state.goals.find(x=>x.id===k);try{switch(a){case 'go':go(k);break;case 'close':$('#modal').close();break;case 'day':routineDate=k==='0'?today():plus(routineDate,Number(k));render();break;case 'jump':routineDate=k;render();break;case 'week':week=k==='0'?weekOf(today()):plus(week,Number(k));render();break;case 'select':if(e.status!=='planned'&&e.status!=='deferred')throw Error('Change the status of a recorded exam instead.');if(!e.selected&&selectedCount(e.date)>=2)throw Error('Maximum two exams per date. Unselect another first.');e.selected=!e.selected;e.status='planned';e.manual=true;change();break;case 'auto':autoPick();change();toast('Selections recalculated.');break;case 'editExam':editExam(k);break;case 'result':result(k);break;case 'status':editStatus(k);break;case 'goalPlus':progress(g,weekProgress(g)+g.step);break;case 'goalMinus':progress(g,weekProgress(g)-g.step);break;case 'editGoal':case 'editWord':case 'editTopic':case 'editBook':case 'editJob':editGeneric(a,k);break;case 'log':form('Log study session','log','',field('Date',today(),'date','required')+field('Subject','','text','required')+field('Minutes',30,'number','min="1" required'));break;case 'reveal':reveal=true;render();break;case 'nextWord':flashIndex++;reveal=false;render();break;case 'reviewWord':{let [wid,known]=k.split('|'),w=state.words.find(x=>x.id===wid);w.reps=known==='1'?w.reps+1:0;w.due=plus(today(),known==='1'?[1,3,7,14,30,60][Math.min(w.reps-1,5)]:0);if(known==='0')flashIndex++;reveal=false;change();break}case 'topicReview':{let t=state.topics.find(x=>x.id===k);t.reps=(t.reps||0)+1;t.due=plus(today(),[1,3,7,14,30][Math.min(t.reps-1,4)]);change();break}case 'wordImport':dialog('Import vocabulary',`<form data-form="wordImport"><label>One line per word: word | meaning | synonyms | antonyms | example<textarea name="raw" required></textarea></label><button class="primary">Import</button></form>`);break;case 'import':importDialog();break;case 'fetchRoutine':{let response=await fetch('https://raw.githubusercontent.com/totoroKr/project-2029/main/routine-feed.json',{cache:'no-store'});if(!response.ok)throw Error('Public routine feed not ready; paste the routine manually.');let feed=await response.json();preview(parseRoutine(JSON.stringify(feed.exams)));break}case 'refreshRoutine':await refreshPublicRoutine(true);break;case 'commitImport':{let chosen=[...document.querySelectorAll('.importCheck:checked')].map(c=>importBuffer[Number(c.value)]),n=0;for(let r of chosen){if(state.exams.some(e=>e.date===r.date&&e.programme===r.programme&&e.topic===r.topic))continue;state.exams.push({...r,id:id(),selected:false,status:'planned',note:'',result:null});n++}autoPick();$('#modal').close();change();toast(n+' exams imported.');break}case 'delete':{let [kind,key]=k.split('|');if(!confirm('Delete this item?'))break;let col={editExam:'exams',editGoal:'goals',editWord:'words',editTopic:'topics',editBook:'books',editJob:'jobs'}[kind];state[col]=state[col].filter(x=>x.id!==key);$('#modal').close();change();break}case 'backup':download('project2029-'+today()+'.json',JSON.stringify(state,null,2));break;case 'csv':{let cell=s=>'"'+String(s??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';download('project2029-results.csv',[['date','programme','topic','status','score','max','correct','wrong','rank'],...state.exams.filter(e=>e.result).map(e=>[e.date,PROGRAMS[e.programme],e.topic,e.status,e.result.score,e.result.max,e.result.correct,e.result.wrong,e.result.rank])].map(r=>r.map(cell).join(',')).join('\n'),'text/csv');break}case 'restore':dialog('Restore backup',`<form data-form="restore"><p>This replaces local data. Export your current backup first.</p><input type="file" name="file" accept="application/json,.json" required><button class="primary">Restore</button></form>`);break;case 'sync':dialog('Private server sync',`<form data-form="sync"><label>Server token<input type="password" name="token" required value="${esc(sessionStorage.getItem('p2029-token')||'')}"></label>${options('Direction',[['upload','Upload local state (replace server copy)'],['download','Download server state (replace local copy)']],'upload')}<p class="muted">Use only on your private HTTPS deployment. Export a backup before overwriting.</p><button class="primary">Sync now</button></form>`);break;case 'notify':if(!('Notification'in window))throw Error('Notifications are not supported in this browser.');{let p=await Notification.requestPermission();toast('Notification permission: '+p);if(p==='granted')notify('Project 2029','Notifications enabled while the app is open.','test'+Date.now());}break;case 'push':{let info=await api('push-config');if(!info.publicKey)throw Error('Background push is not configured on this server.');if(!navigator.serviceWorker)throw Error('HTTPS or localhost is required.');let p=await Notification.requestPermission();if(p!=='granted')throw Error('Notification permission not granted.');let reg=await navigator.serviceWorker.ready;let raw=atob(info.publicKey.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(info.publicKey.length/4)*4,'=')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));let sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('subscribe',sub.toJSON());await api('sync',state);toast('Background push subscription saved. Sync after changes.');break}case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('Use browser menu → Install app / Add to Home screen on HTTPS or localhost.');break;case 'readNotices':state.notices.forEach(n=>n.read=true);change();$('#modal').close();break}}catch(err){toast(err.message||String(err))}});
document.addEventListener('submit',async ev=>{let f=ev.target;if(!f.dataset.form)return;ev.preventDefault();let a=f.dataset.form,k=f.dataset.key||'',d=new FormData(f),v=n=>String(d.get(n)??'').trim(),num=n=>Number(v(n)),e=state.exams.find(x=>x.id===k);try{if(a==='previewImport'){preview(parseRoutine(v('raw')));return}if(a==='editExam'){let x={...e,id:k||id(),date:v('Date'),programme:v('Programme'),topic:v('Topic'),marks:v('Maximum marks'),end:v('Closing time'),note:v('Notes / references'),selected:e?.selected||false,status:e?.status||'planned',result:e?.result||null};if(!x.topic)throw Error('Enter an exam topic.');if(e?.selected&&x.date!==e.date&&selectedCount(x.date)>=2)throw Error('Both slots on that date are used.');replace(state.exams,k,x);autoPick()}else if(a==='status'){setAttendance(e,v('Status'),v('Recovery date'));e.note=v('Notes')}else if(a==='result'){if(num('Net score')>num('Maximum marks'))throw Error('Net score cannot exceed maximum marks.');let photo=await smallPhoto(d.get('photo'));setAttendance(e,v('Attendance'),v('Recovery date'));e.result={score:num('Net score'),max:num('Maximum marks'),correct:v('Correct'),wrong:v('Wrong'),skipped:v('Skipped'),penalty:v('Negative marks'),rank:v('Rank'),minutes:v('Minutes'),weak:v('Weak topics'),photo:photo||e.result?.photo||''};if(e.result.weak&&!state.topics.some(t=>t.name===e.result.weak))state.topics.push({id:id(),name:e.result.weak,note:PROGRAMS[e.programme],due:plus(today(),1),reps:0})}else if(a==='editGoal')replace(state.goals,k,{id:k||id(),name:v('Name'),unit:v('Unit'),target:num('Target'),step:num('Increment')});else if(a==='editWord'){let old=state.words.find(w=>w.id===k)||{};replace(state.words,k,{...old,id:k||id(),word:v('Word'),meaning:v('Meaning'),synonyms:v('Synonyms'),antonyms:v('Antonyms'),example:v('Example'),due:old.due||today(),reps:old.reps||0})}else if(a==='editTopic'){let old=state.topics.find(t=>t.id===k)||{};replace(state.topics,k,{...old,id:k||id(),name:v('Name'),note:v('Notes'),due:v('Due'),reps:old.reps||0})}else if(a==='editBook'){if(num('Total units')&&num('Completed units')>num('Total units'))throw Error('Completed units exceed total.');replace(state.books,k,{id:k||id(),name:v('Name'),total:num('Total units'),done:num('Completed units')})}else if(a==='editJob')replace(state.jobs,k,{id:k||id(),org:v('Organisation'),role:v('Role'),deadline:v('Deadline'),exam:v('Exam date'),status:v('Status'),note:v('Notes / circular link')});else if(a==='log')state.logs.push({id:id(),date:v('Date'),subject:v('Subject'),minutes:num('Minutes')});else if(a==='wordImport'){for(let l of v('raw').split('\n')){let [word,meaning,synonyms='',antonyms='',example='']=l.split('|').map(s=>s.trim());if(word&&meaning&&!state.words.some(w=>w.word.toLowerCase()===word.toLowerCase()))state.words.push({id:id(),word,meaning,synonyms,antonyms,example,due:today(),reps:0})}}else if(a==='restore'){let data=validated(JSON.parse(await d.get('file').text()));if(!confirm('Replace all local data with this backup?'))return;state=data}else if(a==='sync'){let token=v('token');sessionStorage.setItem('p2029-token',token);if(!confirm('Replace '+(v('Direction')==='upload'?'server':'local')+' data?'))return;if(v('Direction')==='upload')await api('sync',state,token);else state=validated((await api('sync',undefined,token)).state);toast('Sync successful.')}$('#modal').close();change();reminders()}catch(err){toast(err.message||String(err))}});
document.addEventListener('change',ev=>{let x=ev.target;if(x.id==='rdate'&&x.value){routineDate=x.value;render()}else if(x.id==='programFilter'){filter=x.value;render()}else if(x.classList.contains('program')){state.settings.enabled=[...document.querySelectorAll('.program:checked')].map(i=>i.value);for(let e of state.exams)if(!state.settings.enabled.includes(e.programme)&&e.status==='planned'&&e.date>=today()&&!e.manual)e.selected=false;autoPick();change()}else if(['hours','brief','evening','dark','reminders'].includes(x.id)){state.settings[x.id]=x.type==='checkbox'?x.checked:x.type==='number'?clamp(Number(x.value),1,12):x.value;change()}});
