const CLOUD_URL='https://qgqmsqpphjtaediacutg.supabase.co';
const CLOUD_KEY='sb_publishable_CQ2W6UejzZbH8-Fh6AjAKw_PyAoDkIF';
let cloudSession=null, cloudRev=null, cloudBaseline=null, cloudReady=false, cloudBusy=false, cloudTimer=null, cloudMessage='Not signed in';
function cloudStatus(msg){cloudMessage=msg;let el=$('#cloudStatus');if(el)el.textContent=msg;let st=$('#storageStatus');if(st)st.textContent=cloudReady?'Local + cloud':'Local storage';}
async function cloudRequest(path,{method='GET',body,token,prefer}={}){
 const headers={apikey:CLOUD_KEY,'Content-Type':'application/json'};
 if(token)headers.Authorization='Bearer '+token;if(prefer)headers.Prefer=prefer;
 const response=await fetch(CLOUD_URL+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});
 const data=await response.json().catch(()=>null);
 if(!response.ok)throw Error(data?.msg||data?.message||data?.error_description||('Supabase HTTP '+response.status));
 return data;
}
function cloudRemember(s){cloudSession={access_token:s.access_token,refresh_token:s.refresh_token,user:s.user,expires:Date.now()+(s.expires_in||3600)*1000};}
async function cloudToken(){
 if(!cloudSession)throw Error('Sign in first.');
 if(cloudSession.expires>Date.now()+60000)return cloudSession.access_token;
 cloudRemember(await cloudRequest('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:cloudSession.refresh_token}}));
 return cloudSession.access_token;
}
function cloudPath(){return '/rest/v1/study_state?user_id=eq.'+encodeURIComponent(cloudSession.user.id);}
async function cloudRead(token){const rows=await cloudRequest(cloudPath()+'&select=state,updated_at',{token});return rows[0]||null;}
function cloudPanel(){return '<div class="card"><h2>Private cloud sync</h2><p id="cloudStatus">'+esc(cloudMessage)+'</p><p class="muted">Sign in on both devices. Choose the initial copy. While open, the app syncs automatically. Concurrent edits pause sync instead of overwriting either copy. Sign in again after reopening.</p><div class="actions"><button data-cloud="login">Sign in</button><button data-cloud="now">Sync now</button><button data-cloud="resolve">Choose cloud or local copy</button><button data-cloud="logout">Sign out</button></div></div>';}
function cloudPrompt(){dialog('Sign in to Project 2029','<form id="cloudLogin"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="muted">Use your Supabase account. Password goes directly to Supabase and is not stored by this app.</p><button class="primary" type="submit">Sign in</button></form>');}
function cloudPause(message){cloudReady=false;clearTimeout(cloudTimer);cloudStatus(message);}
async function cloudChoose(){
 if(!cloudSession)throw Error('Sign in first.');
 if(cloudBusy)throw Error('Sync in progress.');
 cloudPause('Choose a copy before enabling sync.');cloudBusy=true;
 let upload=false;
 try{
  const remote=await cloudRead(await cloudToken());
  if(remote){
   validated(remote.state);
   if(confirm('Use the cloud copy? OK = download cloud copy. Cancel = review local upload option.')){
    localStorage.setItem('project2029-pre-cloud-backup',JSON.stringify(state));
    state=remote.state;cloudRev=remote.updated_at;cloudBaseline=JSON.stringify(state);cloudReady=true;save();render();cloudStatus('Cloud copy loaded.');
   }else if(confirm('Replace cloud copy with this device’s local data? Export a backup first if unsure.')){
    cloudRev=remote.updated_at;cloudBaseline=null;cloudReady=true;upload=true;
   }
  }else if(confirm('No cloud data yet. Upload this device’s study progress?')){
   cloudRev=null;cloudBaseline=null;cloudReady=true;upload=true;
  }
 }finally{cloudBusy=false;}
 if(upload)await cloudSync();
}
function cloudQueue(){if(!cloudReady)return;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudSync().catch(e=>cloudStatus('Sync pending: '+e.message)),1800);}
async function cloudSync(){
 if(!cloudReady||cloudBusy)return;cloudBusy=true;
 try{
  const snapshot=JSON.stringify(state), token=await cloudToken(), remote=await cloudRead(token);
  if((remote?.updated_at||null)!==cloudRev){
   if(snapshot===cloudBaseline&&remote&&JSON.stringify(state)===snapshot){
    validated(remote.state);localStorage.setItem('project2029-pre-cloud-backup',snapshot);
    state=remote.state;cloudRev=remote.updated_at;cloudBaseline=JSON.stringify(state);save();render();cloudStatus('Updated from cloud.');return;
   }
   cloudPause('Cloud changed on another device. Export a backup and choose a copy.');return;
  }
  if(snapshot===cloudBaseline){cloudStatus('Cloud is up to date.');return;}
  const updated_at=new Date(Math.max(Date.now(),cloudRev?Date.parse(cloudRev)+1:0)).toISOString();
  const payload={state:JSON.parse(snapshot),updated_at};
  let rows;
  if(cloudRev)rows=await cloudRequest(cloudPath()+'&updated_at=eq.'+encodeURIComponent(cloudRev),{method:'PATCH',token,body:payload,prefer:'return=representation'});
  else rows=await cloudRequest('/rest/v1/study_state',{method:'POST',token,body:{...payload,user_id:cloudSession.user.id},prefer:'return=representation'});
  if(!Array.isArray(rows)||rows.length!==1){cloudPause('Concurrent update detected. Choose a copy.');return;}
  cloudRev=rows[0].updated_at;cloudBaseline=snapshot;cloudStatus('Synced at '+new Date().toLocaleTimeString());
  if(JSON.stringify(state)!==snapshot)cloudQueue();
 }finally{cloudBusy=false;}
}
document.addEventListener('submit',async ev=>{
 if(ev.target.id!=='cloudLogin')return;ev.preventDefault();
 const form=ev.target,d=new FormData(form),b=form.querySelector('button');b.disabled=true;
 try{
  const session=await cloudRequest('/auth/v1/token?grant_type=password',{method:'POST',body:{email:String(d.get('email')),password:String(d.get('password'))}});
  if(!session?.user?.id||!session.access_token)throw Error('Login failed.');
  cloudRemember(session);form.reset();$('#modal').close();cloudStatus('Signed in.');await cloudChoose();
 }catch(e){toast(e.message);cloudStatus('Cloud setup: '+e.message);}finally{b.disabled=false;}
});
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-cloud]');if(!b)return;
 try{
  if(b.dataset.cloud==='login'){if(cloudSession)await cloudChoose();else cloudPrompt();}
  if(b.dataset.cloud==='now'){if(!cloudReady)throw Error('Sign in and choose a data copy first.');await cloudSync();toast(cloudMessage);}
  if(b.dataset.cloud==='resolve')await cloudChoose();
  if(b.dataset.cloud==='logout'){if(cloudBusy)throw Error('Sync in progress.');cloudPause('Signed out. Local progress remains.');cloudSession=null;cloudRev=null;cloudBaseline=null;toast(cloudMessage);}
 }catch(e){toast(e.message);}
});
setInterval(()=>{if(cloudReady&&!document.hidden)cloudSync().catch(e=>cloudStatus('Sync pending: '+e.message));},60000);

